// Route tests for the Jotter demo (real HTTP via fetch, no Kane).
// They pin the demo's contract: the three seeded bugs are present, and guests are blocked.
// Run: npx vitest run --root demo
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createApp } from '../app.js';
import { openDb } from '../db.js';
import { DEFAULT_PASSWORDS, DEFAULT_TOKENS, loadTokens, seed } from '../seed.js';

const ALICE = { email: 'alice@jotter.test', password: DEFAULT_PASSWORDS.alice, token: DEFAULT_TOKENS.alice };
const BOB = { email: 'bob@jotter.test', password: DEFAULT_PASSWORDS.bob, token: DEFAULT_TOKENS.bob };

let server;
let base;

beforeAll(async () => {
  const db = await openDb(); // in-memory
  seed(db, { tokens: { ...DEFAULT_TOKENS }, passwords: { ...DEFAULT_PASSWORDS } });
  server = createApp(db).listen(0, '127.0.0.1');
  await new Promise((r) => server.once('listening', r));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterAll(() => new Promise((r) => server.close(r)));

/** A tiny cookie-keeping client. Redirects are not followed so tests can assert on them. */
function client() {
  let cookie = '';
  return async function req(method, url, form) {
    const res = await fetch(base + url, {
      method,
      redirect: 'manual',
      headers: {
        ...(cookie ? { cookie } : {}),
        ...(form ? { 'content-type': 'application/x-www-form-urlencoded' } : {}),
      },
      body: form ? new URLSearchParams(form).toString() : undefined,
    });
    const set = res.headers.get('set-cookie');
    if (set) cookie = set.split(';')[0];
    return { status: res.status, location: res.headers.get('location'), headers: res.headers, text: await res.text() };
  };
}

async function loginAs(who) {
  const req = client();
  const res = await req('POST', '/login', { email: who.email, password: who.password });
  expect(res.status).toBe(302);
  return req;
}

describe('guests are blocked (no false alarms)', () => {
  const guest = client();

  it('GET /notes/1001 redirects to /login without the token', async () => {
    const res = await guest('GET', '/notes/1001');
    expect(res.status).toBe(302);
    expect(res.location).toBe('/login?next=%2Fnotes%2F1001');
    expect(res.text).not.toContain(ALICE.token);
  });

  it('GET /api/notes/1001 is 401 without the token', async () => {
    const res = await guest('GET', '/api/notes/1001');
    expect(res.status).toBe(401);
    expect(res.text).not.toContain(ALICE.token);
  });

  it('every private page redirects to /login', async () => {
    for (const url of ['/notes', '/notes/new', '/notes/1002', '/account', '/pro/export']) {
      const res = await guest('GET', url);
      expect(res.status, url).toBe(302);
      expect(res.location, url).toMatch(/^\/login\?next=/);
    }
  });

  it('POST /api/export is 401', async () => {
    const res = await guest('POST', '/api/export');
    expect(res.status).toBe(401);
  });
});

describe('positive controls', () => {
  it("Alice sees her own note 1001 with her token, in the page and the API", async () => {
    const alice = await loginAs(ALICE);
    const pageRes = await alice('GET', '/notes/1001');
    expect(pageRes.status).toBe(200);
    expect(pageRes.text).toContain(`Passport no. ${ALICE.token}`);
    const api = await alice('GET', '/api/notes/1001');
    expect(JSON.parse(api.text)).toMatchObject({ id: 1001, owner_email: ALICE.email, body: `Passport no. ${ALICE.token}` });
  });

  it("Bob's /notes lists only his note and /account shows his token in the bio", async () => {
    const bob = await loginAs(BOB);
    const list = await bob('GET', '/notes');
    expect(list.text).toContain('href="/notes/1002"');
    expect(list.text).toContain(BOB.token);
    expect(list.text).not.toContain('href="/notes/1001"');
    expect(list.text).not.toContain(ALICE.token);
    const account = await bob('GET', '/account');
    expect(account.text).toContain(BOB.token);
    expect(account.text).toContain('Jotter Free');
    expect(account.text).not.toContain(ALICE.token);
  });

  it('wrong password is rejected', async () => {
    const req = client();
    const res = await req('POST', '/login', { email: BOB.email, password: '[redacted]' }); // notyours:allow-secret (fake test value)
    expect(res.status).toBe(401);
    expect(res.text).toContain('Wrong email or password');
  });
});

describe('seeded bugs are present', () => {
  it('SEEDED BUG #1: Bob can open Alice\'s note page /notes/1001', async () => {
    const bob = await loginAs(BOB);
    const res = await bob('GET', '/notes/1001');
    expect(res.status).toBe(200);
    expect(res.text).toContain(ALICE.token);
  });

  it('SEEDED BUG #2: Bob can fetch Alice\'s full record from /api/notes/1001', async () => {
    const bob = await loginAs(BOB);
    const res = await bob('GET', '/api/notes/1001');
    expect(res.status).toBe(200);
    expect(JSON.parse(res.text)).toMatchObject({ id: 1001, owner_id: 1, owner_email: ALICE.email });
    expect(res.text).toContain(ALICE.token);
  });

  it('SEEDED BUG #3: free Bob has no export button, but POST /api/export works anyway', async () => {
    const bob = await loginAs(BOB);
    const ui = await bob('GET', '/pro/export');
    expect(ui.status).toBe(200);
    expect(ui.text).not.toContain('action="/api/export"');
    expect(ui.text).toContain('Export is a Jotter Pro feature');

    const res = await bob('POST', '/api/export');
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toMatch(/^text\/plain/);
    expect(res.headers.get('content-disposition')).toContain('jotter-export.txt');
    expect(res.text).toContain(BOB.token);
    expect(res.text).not.toContain(ALICE.token);
  });

  it('GET /api/export is 405 with Allow: POST (never a 404), for Bob and for guests', async () => {
    const bob = await loginAs(BOB);
    for (const req of [bob, client()]) {
      const res = await req('GET', '/api/export');
      expect(res.status).toBe(405);
      expect(res.headers.get('allow')).toBe('POST');
      expect(res.text).not.toContain(BOB.token);
    }
  });

  it('Pro Alice sees the export button and exports only her notes', async () => {
    const alice = await loginAs(ALICE);
    const ui = await alice('GET', '/pro/export');
    expect(ui.text).toContain('action="/api/export"');
    const res = await alice('POST', '/api/export');
    expect(res.text).toContain(ALICE.token);
    expect(res.text).not.toContain(BOB.token);
  });
});

describe('CSV export', () => {
  it('Pro Alice can pick CSV and gets only her notes as a CSV attachment', async () => {
    const alice = await loginAs(ALICE);
    const ui = await alice('GET', '/pro/export');
    expect(ui.text).toContain('name="format"');
    expect(ui.text).toContain('value="csv"');

    const res = await alice('POST', '/api/export', { format: 'csv' });
    expect(res.status).toBe(200);
    expect(res.headers.get('content-type')).toMatch(/^text\/csv/);
    expect(res.headers.get('content-disposition')).toContain('jotter-export.csv');
    const lines = res.text.split('\r\n');
    expect(lines[0]).toBe('id,title,body,created_at');
    expect(lines[1]).toMatch(/^1001,Travel documents,Passport no\. /);
    expect(res.text).toContain(ALICE.token);
    expect(res.text).not.toContain(BOB.token);
  });

  it('quotes commas, quotes and newlines, and defuses formula-like cells', async () => {
    const req = client();
    await req('POST', '/signup', { name: 'Finn', email: 'finn@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
    await req('POST', '/notes/new', { title: 'a, "b"', body: 'line1\nline2' });
    await req('POST', '/notes/new', { title: '=HYPERLINK("x")', body: '@sum' });
    const res = await req('POST', '/api/export', { format: 'csv' });
    expect(res.status).toBe(200); // free user: still allowed because of SEEDED BUG #3
    expect(res.text).toContain(',"a, ""b""","line1\nline2",');
    expect(res.text).toContain(`,"'=HYPERLINK(""x"")",'@sum,`);
  });

  it('no format still means plain text, and unknown formats are 400', async () => {
    const alice = await loginAs(ALICE);
    const txt = await alice('POST', '/api/export', { format: 'txt' });
    expect(txt.headers.get('content-type')).toMatch(/^text\/plain/);
    const bad = await alice('POST', '/api/export', { format: 'xlsx' });
    expect(bad.status).toBe(400);
    expect(bad.text).not.toContain(ALICE.token);
  });
});

describe('happy paths', () => {
  it('signup -> create note -> view it -> logout', async () => {
    const req = client();
    const signup = await req('POST', '/signup', { name: 'Carol', email: 'carol@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
    expect(signup.status).toBe(302);
    expect(signup.location).toBe('/notes');

    const empty = await req('GET', '/notes');
    expect(empty.text).toContain('No notes yet');

    const created = await req('POST', '/notes/new', { title: 'Shopping', body: 'eggs & <milk>' });
    expect(created.status).toBe(302);
    const id = Number(created.location.split('/').pop());
    expect(id).toBeGreaterThan(1002);

    const view = await req('GET', created.location);
    expect(view.status).toBe(200);
    expect(view.text).toContain('eggs &amp; &lt;milk&gt;'); // escaped

    const account = await req('GET', '/account');
    expect(account.text).toContain('Jotter Free');

    const out = await req('GET', '/logout');
    expect(out.location).toBe('/login');
    expect((await req('GET', '/notes')).status).toBe(302);
  });

  it('login honours a safe ?next= and ignores an off-site one', async () => {
    const req = client();
    const ok = await req('POST', '/login?next=%2Faccount', { email: BOB.email, password: BOB.password });
    expect(ok.location).toBe('/account');
    const req2 = client();
    const evil = await req2('POST', '/login?next=%2F%2Fevil.test', { email: BOB.email, password: BOB.password });
    expect(evil.location).toBe('/notes');
  });

  it('duplicate signup and empty notes are rejected', async () => {
    const req = client();
    const dup = await req('POST', '/signup', { name: 'B', email: BOB.email, password: '[redacted]' }); // notyours:allow-secret (fake test value)
    expect(dup.status).toBe(400);
    const bob = await loginAs(BOB);
    const bad = await bob('POST', '/notes/new', { title: '', body: '' });
    expect(bad.status).toBe(400);
  });

  it('unknown note ids are 404', async () => {
    const bob = await loginAs(BOB);
    expect((await bob('GET', '/notes/999999')).status).toBe(404);
    expect((await bob('GET', '/api/notes/abc')).status).toBe(404);
  });
});

describe('duplicate note', () => {
  it('owner sees a Duplicate button and gets an independent copy', async () => {
    const req = client();
    await req('POST', '/signup', { name: 'Dana', email: 'dana@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
    const created = await req('POST', '/notes/new', { title: 'Recipe', body: 'flour\n& <sugar>' });
    const id = Number(created.location.split('/').pop());

    const view = await req('GET', `/notes/${id}`);
    expect(view.text).toContain(`action="/notes/${id}/duplicate"`);

    const dup = await req('POST', `/notes/${id}/duplicate`);
    expect(dup.status).toBe(302);
    const copyId = Number(dup.location.split('/').pop());
    expect(copyId).toBeGreaterThan(id);

    const copy = await req('GET', dup.location);
    expect(copy.status).toBe(200);
    expect(copy.text).toContain('Copy of Recipe');
    expect(copy.text).toContain('flour\n&amp; &lt;sugar&gt;');

    const list = await req('GET', '/notes');
    expect(list.text).toContain(`href="/notes/${id}"`);
    expect(list.text).toContain(`href="/notes/${copyId}"`);
  });

  it('long titles stay within the 200-character limit', async () => {
    const req = client();
    await req('POST', '/signup', { name: 'Eve', email: 'eve@jotter.test', password: '[redacted]' }); // notyours:allow-secret (fake test value)
    const created = await req('POST', '/notes/new', { title: 'x'.repeat(200), body: 'b' });
    const dup = await req('POST', `${created.location}/duplicate`);
    const json = await req('GET', `/api/notes/${dup.location.split('/').pop()}`);
    expect(JSON.parse(json.text).title).toBe(`Copy of ${'x'.repeat(192)}`);
  });

  it("Bob cannot duplicate Alice's note into his account, and sees no button for it", async () => {
    const bob = await loginAs(BOB);
    const view = await bob('GET', '/notes/1001'); // readable only because of SEEDED BUG #1
    expect(view.text).not.toContain('/duplicate');

    const dup = await bob('POST', '/notes/1001/duplicate');
    expect(dup.status).toBe(404);
    expect(dup.text).not.toContain(ALICE.token);
    const list = await bob('GET', '/notes');
    expect(list.text).not.toContain(ALICE.token);
    expect(list.text).not.toContain('Travel documents');
  });

  it('guests are redirected to /login and bad ids are 404', async () => {
    const guest = client();
    const res = await guest('POST', '/notes/1001/duplicate');
    expect(res.status).toBe(302);
    expect(res.location).toMatch(/^\/login\?next=/);
    const bob = await loginAs(BOB);
    expect((await bob('POST', '/notes/abc/duplicate')).status).toBe(404);
    expect((await bob('POST', '/notes/999999/duplicate')).status).toBe(404);
  });
});

describe('seed tokens', () => {
  it('reads tokens from identities.json (array or keyed object), ignoring invalid ones', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jotter-'));
    const arr = path.join(dir, 'arr.json');
    fs.writeFileSync(arr, JSON.stringify([{ id: 'alice', token: '[redacted]' }, { id: 'bob', token: 'bad' }]));
    expect(loadTokens([arr])).toEqual({ alice: 'NY-ALICE-ABCDEFGHIJKL', bob: DEFAULT_TOKENS.bob });

    const obj = path.join(dir, 'obj.json');
    fs.writeFileSync(obj, JSON.stringify({ bob: { token: '[redacted]' } }));
    expect(loadTokens([path.join(dir, 'missing.json'), obj])).toEqual({ alice: DEFAULT_TOKENS.alice, bob: 'NY-BOB-MNOPQRSTUVWX' });

    expect(loadTokens([path.join(dir, 'missing.json')])).toEqual(DEFAULT_TOKENS);
    fs.rmSync(dir, { recursive: true });
  });

  it('default tokens match the notyours canary format', () => {
    expect(DEFAULT_TOKENS.alice).toMatch(/^NY-ALICE-[A-Z2-7]{12}$/);
    expect(DEFAULT_TOKENS.bob).toMatch(/^NY-BOB-[A-Z2-7]{12}$/);
  });
});
// /pro/export (page) and POST /api/export (download).
//
// The plan gate is enforced server-side on POST /api/export (formerly SEEDED BUG #3).
import { Router } from 'express';
import { requireLogin, requireLoginApi } from '../session.js';
import { esc, page } from '../views.js';

export function proRoutes(db) {
  const r = Router();

  r.get('/pro/export', requireLogin, (req, res) => {
    const isPro = req.user.plan === 'pro';
    const { n } = db.get('SELECT COUNT(*) AS n FROM notes WHERE owner_id = ?', [req.user.id]);
    const action = isPro
      ? `<form method="post" action="/api/export">
<label for="export-format">Format</label>
<select id="export-format" name="format">
<option value="txt" selected>Plain text (.txt)</option>
<option value="csv">CSV (.csv)</option>
</select>
<button type="submit">Export my notes</button>
</form>`
      : `<p><span class="badge pro">PRO</span> Export is a Jotter Pro feature. Upgrade to Pro to download your notes.</p>`;
    const body = `<h1>Export notes</h1>
<div class="card">
<p>Download ${n === 1 ? 'your note' : `all ${esc(n)} of your notes`} as a plain text or CSV file.</p>
${action}
</div>`;
    res.send(page({ title: 'Export notes', user: req.user, active: 'export', body }));
  });

  // Export is a Pro feature: enforce the plan here, not only by hiding the button on /pro/export.
  r.post('/api/export', requireLoginApi, (req, res) => {
    if (req.user.plan !== 'pro') {
      return res.status(403).json({ error: 'export requires Jotter Pro' });
    }
    const format = req.body?.format ?? 'txt';
    if (format !== 'txt' && format !== 'csv') {
      return res.status(400).json({ error: 'unsupported format', formats: ['txt', 'csv'] });
    }
    const notes = db.all('SELECT id, title, body, created_at FROM notes WHERE owner_id = ? ORDER BY id', [req.user.id]);
    if (format === 'csv') {
      const rows = [['id', 'title', 'body', 'created_at'], ...notes.map((n) => [n.id, n.title, n.body, n.created_at])];
      res.set('Content-Type', 'text/csv; charset=utf-8');
      res.set('Content-Disposition', 'attachment; filename="jotter-export.csv"');
      return res.send(rows.map((row) => row.map(csvCell).join(',')).join('\r\n') + '\r\n');
    }
    const text = [
      `Jotter export for ${req.user.email}`,
      `Exported ${new Date().toISOString()}`,
      '',
      ...notes.flatMap((n) => [`# ${n.title} (note ${n.id}, ${n.created_at})`, n.body, '']),
    ].join('\n');
    res.set('Content-Type', 'text/plain; charset=utf-8');
    res.set('Content-Disposition', 'attachment; filename="jotter-export.txt"');
    res.send(text);
  });

  // Export is POST-only. Any other method gets an explicit 405 (not a 404), so a wrong-method probe
  // can't be mistaken for "denied". Checked before login, as HTTP method errors usually are.
  r.all('/api/export', (_req, res) => {
    res.set('Allow', 'POST');
    res.status(405).json({ error: 'method not allowed', allow: ['POST'] });
  });

  return r;
}

/**
 * One RFC 4180 CSV field. Text starting with = + - @ (or a tab/CR) gets a leading apostrophe so
 * spreadsheet apps don't run it as a formula.
 */
function csvCell(value) {
  let s = String(value ?? '');
  if (typeof value === 'string' && /^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\r\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
}
